#include <cudnn.h>

constexpr int kN = 1024;
constexpr int kBatchSize = 1024;

__global__ void spectral_derivative_kernel(const float* x, float* dx, int batch, cudaStream_t stream) {
    int b = blockIdx.x;
    int n = threadIdx.x;

    // Allocate memory for the FFT
    cudaMathdxFFTPlan plan;
    cudaMathdxFFTPlanCreate(&plan, kN, CUDA_MATHDX_FFT_R2C);

    // Execute the FFT
    cudaMathdxFFTExec(plan, x + b * kN, dx + b * kN, stream);

    // Apply the derivative weighting
    for (int k = 0; k < kN; ++k) {
        float w = 0.0f;
        if (k < 512) {
            w = static_cast<float>(k);
        } else if (k == 512) {
            w = 0.0f;
        } else {
            w = static_cast<float>(k - 1024);
        }

        // Apply the derivative
        dx[b * kN + k] *= static_cast<float>(CUDA_MATHDX_PI) * w;
    }

    // Inverse FFT to get the derivative
    cudaMathdxFFTExec(plan, dx + b * kN, dx + b * kN, stream);

    // Normalize the result
    for (int k = 0; k < kN; ++k) {
        dx[b * kN + k] /= static_cast<float>(kN);
    }
}

