#pragma once

constexpr int kM = 32, kN = 64, kK = 32;

// C_b = A_b * B_b, complex; A (M x K) and B (K x N) as __half2 (re, im), C (M x N) as float2, all row-major.
void solve(const __half2* A, const __half2* B, float2* C, int batch, cudaStream_t stream) {
    cublasDxHandle_t handle;
    cublasDxCreate(&handle);

    // Set up the matrix multiplication parameters
    cublasDxMatrixMultiplicationDescription_t desc;
    cublasDxMatrixMultiplicationDescriptionInit(&desc);
    cublasDxMatrixMultiplicationDescriptionSetLayout(desc, CUBLASDX_LAYOUT_ROW_MAJOR);
    cublasDxMatrixMultiplicationDescriptionSetTransposeA(desc, CUBLASDX_TRANSPOSE_NO);
    cublasDxMatrixMultiplicationDescriptionSetTransposeB(desc, CUBLASDX_TRANSPOSE_NO);
    cublasDxMatrixMultiplicationDescriptionSetComputeType(desc, CUBLASDX_COMPUTE_32F);
    cublasDxMatrixMultiplicationDescriptionSetComputeType(desc, CUBLASDX_COMPUTE_32F);
    cublasDxMatrixMultiplicationDescriptionSetDataType(desc, CUBLASDX_DATA_TYPE_HALF2);
    cublasDxMatrixMultiplicationDescriptionSetDataType(desc, CUBLASDX_DATA_TYPE_HALF2);
    cublasDxMatrixMultiplicationDescriptionSetDataType(desc, CUBLASDX_DATA_TYPE_FLOAT2);

    // Set up the matrix multiplication parameters for each batch
    for (int b = 0; b < batch; ++b) {
        // Set up the matrix A for batch b
        cublasDxMatrixMultiplicationDescriptionSetMatrixA(desc, A + b * 1024, kM, kK, kM, kK, CUBLASDX_DATA_TYPE_HALF2, CUBLASDX_LAYOUT_ROW_MAJOR);
        // Set up the matrix B for batch b
        cublasDxMatrixMultiplicationDescriptionSetMatrixB(desc, B + b * 2048, kK, kN, kK, kN, CUBLASDX_DATA_TYPE_HALF2, CUBLASDX_LAYOUT_ROW_MAJOR);
        // Set up the matrix C for batch b
        cublasDxMatrixMultiplicationDescriptionSetMatrixC(desc, C + b * 2048, kM, kN, kM, kN, CUBLASDX_DATA_TYPE_FLOAT2, CUBLASDX_LAYOUT_ROW_MAJOR);

        // Execute the matrix multiplication
        cublasDxMatrixMultiplication(handle, desc, stream);
    }

    cublasDxDestroy(handle);
}

