void solve(const __half2* A, const __half2* B, float2* C, int batch, cudaStream_t stream) {
    cublasDxHandle_t handle;
    cublasDxCreate(&handle);

    // Set up the GEMM parameters
    cublasDxGemmConfig_t config;
    cublasDxGemmConfigCreate(&config);
    cublasDxGemmConfigSetMatrixLayout(config, CUBLASDX_LAYOUT_ROW_MAJOR);
    cublasDxGemmConfigSetComputeType(config, CUBLASDX_COMPUTE_32F);
    cublasDxGemmConfigSetComputeType(config, CUBLASDX_COMPUTE_32F);
